import{_ as r,a0 as l,w as p,s as i,I as a,x as s,a1 as n,A as o,ao as m}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const W=JSON.parse('{"title":"Linux有問必答：如何創建新的亞馬遜AWS訪問密鑰 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何創建新的亞馬遜AWS訪問密鑰 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何創建新的亞馬遜AWS訪問密鑰 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何創建新的亞馬遜AWS訪問密鑰 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140915 Linux FAQs with Answers--How to create a new Amazon AWS access key","title":"Linux有問必答：如何創建新的亞馬遜AWS訪問密鑰","tag":"201410","desc":""},"relativePath":"201410/20140915 Linux FAQs with Answers--How to create a new Amazon AWS access key.md","filePath":"[post].md"}'),u={name:"201410/20140915 Linux FAQs with Answers--How to create a new Amazon AWS access key.md"};function A(f,t,d,x,w,S){const e=l("Link");return p(),i("div",null,[t[14]||(t[14]=a("h1",{id:"linux有問必答-如何創建新的亞馬遜aws訪問密鑰",tabindex:"-1"},[s("Linux有問必答：如何創建新的亞馬遜AWS訪問密鑰 "),a("a",{class:"header-anchor",href:"#linux有問必答-如何創建新的亞馬遜aws訪問密鑰","aria-label":"Permalink to “Linux有問必答：如何創建新的亞馬遜AWS訪問密鑰”"},"​")],-1)),t[15]||(t[15]=a("blockquote",null,[a("p",null,[a("strong",null,"問題"),s("：我在配置一個需要訪問我的亞馬遜AWS帳號的應用時被要求提供"),a("strong",null,"AWS訪問密鑰ID"),s("和"),a("strong",null,"秘密訪問密鑰"),s("，我怎樣創建一個新的AWS訪問密鑰呢？")])],-1)),t[16]||(t[16]=a("p",null,"亞馬遜AWS安全憑證用於驗證你以及授權任何第三方應用訪問你的AWS帳號，有各種不同的AWS安全憑證可用，如密碼、訪問密鑰、多因素身份驗證、X.509證書等。",-1)),t[17]||(t[17]=a("p",null,"如果你想要創建新的訪問密鑰（訪問密鑰ID和秘密訪問密鑰），請按一下步驟進行。",-1)),a("p",null,[t[1]||(t[1]=s("首先，登錄到",-1)),n(e,{href:"http://aws.amazon.com/console/"},{default:o(()=>[...t[0]||(t[0]=[s("AWS控制台",-1)])]),_:1}),t[2]||(t[2]=s("。",-1))]),t[18]||(t[18]=m('<p>從頂部欄選擇“安全憑證”菜單（圖中紅色方框所示）。</p><p><img src="https://farm4.staticflickr.com/3855/14987093969_b106406596_o.png" alt=""></p><p>在下一頁中，選擇“訪問密鑰（訪問密鑰ID和秘密訪問密鑰）”選項（圖中紅色方框所示）。</p><p><img src="https://farm6.staticflickr.com/5584/15173842295_6110021f8f_z.jpg" alt=""></p><p>在下一頁中，你將看到一個現存訪問密鑰ID列表（如果有的話）。注意，你不能恢復現存訪問密鑰ID的“秘密訪問密鑰”。出於安全的原因，秘密訪問密鑰只能在你創建新訪問密鑰時才可見。</p><p><img src="https://farm4.staticflickr.com/3897/15150859306_cd25d519be_o.png" alt=""></p><p>點擊“創建新訪問密鑰”（見圖示），將會立即創建一個新的訪問密鑰ID和密碼訪問密鑰對。</p><p><img src="https://farm4.staticflickr.com/3919/14987346068_232e8c73cd_z.jpg" alt=""></p><p>要麼下載一個包含有新訪問密鑰的密鑰文件，要麼複製並粘貼新訪問密鑰信息。再次提請牢記，一旦你關閉該窗口，秘密訪問密鑰將不再可用，除非你下載一個密鑰文件。</p><h3 id="多用户aws帳號" tabindex="-1">多用户AWS帳號 <a class="header-anchor" href="#多用户aws帳號" aria-label="Permalink to “多用户AWS帳號”">​</a></h3><p>如果你是作為公司身份創建的帳號，多個僱員共享這一公司帳號，你可能想要使用身份和訪問管理（IAM）來創建並管理他們的訪問密鑰。</p><p>IAM是一個web服務，它允許一個公司管理多個用户及其與一個AWS帳號關聯的安全憑證。使用IAM，多個用户可以作為不同身份登入單一的AWS帳號，並管理他們的安全憑證而不會相互干預對方的密鑰。</p><p>要管理IAM用户，點擊“安全憑證”頁面上的“用户”菜單（見圖示）。</p><p><img src="https://farm6.staticflickr.com/5589/14987486468_a9120b1f8e_z.jpg" alt=""></p><p>然後，你就可以創建一個新的IAM用户並管理他們的安全憑證，比如訪問密鑰之類的東西。</p><hr>',16)),a("p",null,[t[4]||(t[4]=s("via: ",-1)),n(e,{href:"http://ask.xmodulo.com/create-amazon-aws-access-key.html"},{default:o(()=>[...t[3]||(t[3]=[s("http://ask.xmodulo.com/create-amazon-aws-access-key.html",-1)])]),_:1})]),a("p",null,[t[7]||(t[7]=s("譯者：",-1)),n(e,{href:"https://github.com/GOLinux"},{default:o(()=>[...t[5]||(t[5]=[s("GOLinux",-1)])]),_:1}),t[8]||(t[8]=s(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[6]||(t[6]=[s("wxy",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=s("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[9]||(t[9]=[s("LCTT",-1)])]),_:1}),t[12]||(t[12]=s(" 原創翻譯，",-1)),n(e,{href:"http://linux.cn/"},{default:o(()=>[...t[10]||(t[10]=[s("Linux中國",-1)])]),_:1}),t[13]||(t[13]=s(" 榮譽推出",-1))])])}const g=r(u,[["render",A]]);export{W as __pageData,g as default};
